package glitch

import data.glitch_lib

ip_key_substrings := {"ip", "bind-address", "address", "host", "destination"}

matches_ip_key_pattern(key_str) {
    substring := ip_key_substrings[_]
    contains(key_str, substring)
}

get_key_string(key) = str {
    key.ir_type == "String"
    str := key.value
} else {
    key.ir_type == "VariableReference"
    str := key.value
}

all_hashes(node) = hashes {
    hashes := {n |
        walk(node, [path, n])
        n.ir_type == "Hash"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    hashes := all_hashes(parent)
    hash := hashes[_]
    entry := hash.value[_]
    key_str := get_key_string(entry.key)
    matches_ip_key_pattern(key_str)
    entry.value.ir_type == "String"
    entry.value.value == "0.0.0.0"
    result := {
        "type": "sec_invalid_bind",
        "element": entry,
        "path": parent.path,
        "description": "Unrestricted network access detected - IP address 0.0.0.0 implies binding to all interfaces, which is a security risk. (CWE-284)"
    }
}

